import java.util.*;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }

        int target = total / k;
        Arrays.sort(nums);
        if (nums[nums.length - 1] > target) {
            return false;
        }

        int[] buckets = new int[k];
        return place(nums, nums.length - 1, buckets, target);
    }

    private boolean place(int[] nums, int index, int[] buckets, int target) {
        if (index < 0) {
            return true;
        }

        int value = nums[index];
        Set<Integer> triedSums = new HashSet<>();
        for (int bucket = 0; bucket < buckets.length; bucket++) {
            if (buckets[bucket] + value > target) {
                continue;
            }
            if (!triedSums.add(buckets[bucket])) {
                continue;
            }

            buckets[bucket] += value;
            if (place(nums, index - 1, buckets, target)) {
                return true;
            }
            buckets[bucket] -= value;

            if (buckets[bucket] == 0) {
                break;
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }

        int target = total / k;
        Arrays.sort(nums);
        if (nums[nums.length - 1] > target) {
            return false;
        }

        boolean[] used = new boolean[nums.length];
        return fill(nums, used, k, nums.length - 1, 0, target);
    }

    private boolean fill(int[] nums, boolean[] used, int bucketsLeft, int start, int currentSum, int target) {
        if (bucketsLeft == 1) {
            return true;
        }
        if (currentSum == target) {
            return fill(nums, used, bucketsLeft - 1, nums.length - 1, 0, target);
        }

        int previous = -1;
        for (int i = start; i >= 0; i--) {
            if (used[i] || nums[i] == previous || currentSum + nums[i] > target) {
                continue;
            }

            used[i] = true;
            if (fill(nums, used, bucketsLeft, i - 1, currentSum + nums[i], target)) {
                return true;
            }
            used[i] = false;
            previous = nums[i];

            if (currentSum == 0) {
                break;
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }

        int target = total / k;
        for (int num : nums) {
            if (num > target) {
                return false;
            }
        }

        int totalMasks = 1 << nums.length;
        int[] dp = new int[totalMasks];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < totalMasks; mask++) {
            if (dp[mask] == -1) {
                continue;
            }
            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }
                int nextSum = dp[mask] + nums[i];
                if (nextSum > target) {
                    continue;
                }
                int nextMask = mask | (1 << i);
                if (dp[nextMask] == -1) {
                    dp[nextMask] = nextSum % target;
                }
            }
        }

        return dp[totalMasks - 1] == 0;
    }
}

import java.util.*;

class Solution {
    private int[] nums;
    private int target;
    private Map<Integer, Boolean> memo;

    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }

        this.target = total / k;
        for (int num : nums) {
            if (num > target) {
                return false;
            }
        }
        this.nums = nums;
        this.memo = new HashMap<>();
        return search((1 << nums.length) - 1, 0);
    }

    private boolean search(int unusedMask, int currentSum) {
        if (unusedMask == 0) {
            return currentSum == 0;
        }
        if (currentSum == 0 && memo.containsKey(unusedMask)) {
            return memo.get(unusedMask);
        }

        int remaining = unusedMask;
        while (remaining != 0) {
            int bit = remaining & -remaining;
            int index = Integer.numberOfTrailingZeros(bit);
            int nextSum = currentSum + nums[index];
            if (nextSum <= target && search(unusedMask ^ bit, nextSum % target)) {
                if (currentSum == 0) {
                    memo.put(unusedMask, true);
                }
                return true;
            }
            remaining -= bit;
        }

        if (currentSum == 0) {
            memo.put(unusedMask, false);
        }
        return false;
    }
}
